"""Separate overdue reminders (#221): the booking's single
``overdue_reminded_at`` becomes a counter and timestamp per kind on each
item. Items that are overdue now and whose booking was reminded before count
as reminded once (at that time), so running bookings get no burst of mails."""

from datetime import timedelta

from django.db import migrations, models
from django.utils import timezone


def copy_reminded_at(apps, schema_editor):
    Booking = apps.get_model("lending", "Booking")
    BookingItem = apps.get_model("lending", "BookingItem")
    today = timezone.localdate()
    bookings = Booking.objects.filter(
        overdue_reminded_at__isnull=False, status__in=["confirmed", "handed_out"]
    ).values_list("pk", "overdue_reminded_at")
    for booking_id, stamp in bookings.iterator():
        items = BookingItem.objects.filter(
            booking_id=booking_id, returned_at__isnull=True, period__isnull=False
        )
        pickups, returns = [], []
        for item in items:
            if item.handed_out_at is None:
                start = item.period.lower
                if item.is_active and start and timezone.localtime(start).date() < today:
                    pickups.append(item.pk)
            else:
                upper = item.period.upper
                if upper and timezone.localtime(
                    upper - timedelta(microseconds=1)
                ).date() < today:
                    returns.append(item.pk)
        BookingItem.objects.filter(pk__in=pickups).update(
            overdue_pickup_reminders=1, overdue_pickup_reminded_at=stamp
        )
        BookingItem.objects.filter(pk__in=returns).update(
            overdue_return_reminders=1, overdue_return_reminded_at=stamp
        )


def restore_reminded_at(apps, schema_editor):
    """Best effort: the latest reminder of any of the booking's items."""
    Booking = apps.get_model("lending", "Booking")
    BookingItem = apps.get_model("lending", "BookingItem")
    latest = {}
    rows = BookingItem.objects.filter(
        models.Q(overdue_pickup_reminded_at__isnull=False)
        | models.Q(overdue_return_reminded_at__isnull=False)
    ).values_list("booking_id", "overdue_pickup_reminded_at", "overdue_return_reminded_at")
    for booking_id, pickup, ret in rows.iterator():
        for stamp in (pickup, ret):
            if stamp is not None and (
                booking_id not in latest or stamp > latest[booking_id]
            ):
                latest[booking_id] = stamp
    for booking_id, stamp in latest.items():
        Booking.objects.filter(pk=booking_id).update(overdue_reminded_at=stamp)


